CREATE FUNCTION public.protect_super_admin_status() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (NEW.status IS DISTINCT FROM OLD.status OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at) AND (EXISTS(SELECT 1 FROM public.company_super_administrators WHERE user_id=OLD.user_id) OR EXISTS(SELECT 1 FROM public.platform_administrators WHERE user_id=OLD.user_id)) AND coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Remove super administrator authority before deactivating this account'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_super_admin_status BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_super_admin_status();